CREATE OR REPLACE FUNCTION public.snapshot_program_revision(p_program_id uuid) RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_no int; v_snap jsonb; BEGIN IF p_program_id IS NULL THEN RAISE EXCEPTION 'Program required'; END IF; IF auth.uid() IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.programs p WHERE p.id = p_program_id AND p.owner_id = auth.uid()) THEN RAISE EXCEPTION 'Not program owner'; END IF; PERFORM 1 FROM public.programs WHERE id = p_program_id FOR UPDATE; SELECT COALESCE(MAX(revision_no), 0) + 1 INTO v_no FROM public.program_revisions WHERE program_id = p_program_id; SELECT COALESCE(jsonb_agg(jsonb_build_object('id', d.id, 'weekday', d.weekday, 'name', d.name, 'order_index', d.order_index, 'exercises', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', e.id, 'name', e.name, 'default_sets', e.default_sets, 'default_reps', e.default_reps, 'default_reps_min', e.default_reps_min, 'default_rir', e.default_rir, 'default_rest_seconds', e.default_rest_seconds, 'default_weight_kg', e.default_weight_kg, 'order_index', e.order_index) ORDER BY e.order_index) FROM public.program_day_exercises e WHERE e.program_day_id = d.id), '[]'::jsonb)) ORDER BY d.order_index), '[]'::jsonb) INTO v_snap FROM public.program_days d WHERE d.program_id = p_program_id; INSERT INTO public.program_revisions (program_id, revision_no, snapshot, created_by) VALUES (p_program_id, v_no, v_snap, auth.uid()); RETURN v_no; END; $$; REVOKE ALL ON FUNCTION public.snapshot_program_revision(uuid) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.snapshot_program_revision(uuid) TO authenticated, service_role;
